import './style.css';
import {uid,escape as esc,dateKey,emptyWorkspace,emptyPortfolio,safeURL,monthCells,weekCells,moveItem,eventOnDay,normalizeWorkspace,plannerWeek,weekKey,daysUntil,deadlineLabel,validDateKey} from './workspace/model.js';
import {Backend,readConfig,mergeConfig,writeConfig,configured,prepareGoogle,connectGoogle,clearGoogle,googleConnected,listGoogleCalendars,listGoogleEvents,addGoogleEvent} from './workspace/api.js';

const app=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root');
let config={},sharedConfig={},backend,workspace=emptyWorkspace(),portfolio=emptyPortfolio(),ready=false,loading=false;
let view='today',selectedPage=null,selectedProject='',query='',month=new Date(),selectedDay=dateKey(),googleEvents=[],googleCalendars=[],googleLoading=false,googleError='',googleRequestVersion=0,calendarMode='month',weeklyAnchor=dateKey(),planDate=dateKey();
let dirty=false,saving=false,saveError='',saveTimer,changeVersion=0,dragged=null,previewing=false;
const statusLabels={todo:'할 일',doing:'진행 중',done:'완료'};
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4L19 5"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-12 4h2m4 0h2m-8 3h2"/>',file:'<path d="M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9zM14 2v7h7M7 13h10M7 17h7"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',settings:'<path d="M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1M5.6 18.4l2.1-2.1m8.6-8.6 2.1-2.1"/><circle cx="12" cy="12" r="5"/>',logout:'<path d="M10 3H5v18h5m4-14 5 5-5 5m-6-5h11"/>',check:'<path d="m5 12 4 4L19 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',link:'<path d="m10 13 4-4m-6 6-2 2a4 4 0 0 1-6-6l4-4m12 2 2-2a4 4 0 0 0-6-6l-4 4"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.file}</svg>`;
const btn=(label,action,cls='',ic='')=>`<button type="button" class="button ${cls}" data-action="${action}">${ic?icon(ic):''}${label}</button>`;
const small=(label,action)=>`<button type="button" class="mini" data-action="${action}" aria-label="${esc(label)}">${esc(label)}</button>`;
const field=(label,name,value='',type='text',required=false)=>`<label class="field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${required?'required':''} autocomplete="off"></label>`;
const area=(label,name,value='')=>`<label class="field"><span>${label}</span><textarea name="${name}" rows="4">${esc(value)}</textarea></label>`;
const select=(label,name,options,value)=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const dateLabel=(d)=>new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'long'}).format(d);
const matches=(x)=>!query||JSON.stringify(x).toLowerCase().includes(query.toLowerCase());
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4500);}
function dialog(title,html,onSubmit,footer=''){
  modalRoot.innerHTML=`<dialog class="dialog"><form><header><h2>${esc(title)}</h2>${btn('닫기','close','icon-only dialog-close','close')}</header><div class="dialog-body">${html}<p class="form-error" role="alert"></p></div><footer>${footer}${btn('취소','close','quiet')}<button class="button primary" type="submit">저장</button></footer></form></dialog>`;
  const d=modalRoot.querySelector('dialog');d.showModal();d.addEventListener('close',()=>modalRoot.replaceChildren());
  d.addEventListener('click',e=>{if(e.target===d)d.close();});
  d.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(e.target)),e.target);d.close();}catch(err){d.querySelector('.form-error').textContent=err.message;}finally{b.disabled=false;}});
  d.querySelector('input,textarea,select')?.focus();
}
function closeDialog(){modalRoot.querySelector('dialog')?.close();}
function setSaveStatus(){const el=document.querySelector('#save-status');if(el){el.textContent=saveError?'저장 실패 · 재시도':saving?'저장 중…':dirty?'변경됨':'저장됨';el.classList.toggle('failed',Boolean(saveError));}}
function changed(renderNow=true){dirty=true;changeVersion++;saveError='';clearTimeout(saveTimer);saveTimer=setTimeout(()=>flushSave().catch(()=>{}),650);if(renderNow)render();else setSaveStatus();}
async function flushSave(){
  if(!dirty||!ready)return;if(saving){while(saving)await new Promise(r=>setTimeout(r,25));if(saveError)throw Error(saveError);if(dirty)return flushSave();return;}
  saving=true;setSaveStatus();const version=changeVersion,snapshot=structuredClone(workspace);
  try{await backend.save(snapshot);if(version===changeVersion)dirty=false;saveError='';}catch(err){saveError=err.message;toast('저장하지 못했습니다. '+err.message);throw err;}finally{saving=false;setSaveStatus();}
  if(dirty&&!saveError)return flushSave();
}
function header(){return `<header class="topbar"><a href="#/" class="brand"><span class="brand-mark">k.</span><span>kdh044</span></a><nav><a href="#/" class="${!location.hash||location.hash==='#/'?'active':''}">포트폴리오</a><a href="#/planner" class="${location.hash.includes('planner')?'active':''}">${icon('lock')}플래너</a></nav>${ready?btn('편집','portfolio','quiet','settings'):''}</header>`;}
function renderBlock(b,editable=false,index=0){
  const text=esc(b.text),url=safeURL(b.url);let content='';
  if(b.type==='heading')content=`<h3>${text}</h3>`;
  else if(b.type==='divider')content='<hr>';
  else if(b.type==='checkbox')content=`<label class="block-check"><input type="checkbox" ${b.checked?'checked':''} data-check-block="${b.id}" ${editable?'':'disabled'}><span>${text}</span></label>`;
  else if(b.type==='link')content=url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${text||esc(url)} ↗</a>`:`<p>${text}</p>`;
  else if(b.type==='image')content=url?`<figure><img src="${esc(url)}" alt="${text}" loading="lazy"><figcaption>${text}</figcaption></figure>`:'';
  else content=`<p>${text}</p>`;
  return `<div class="content-block" ${editable?`draggable="true" data-block-drag="${b.id}" data-block-index="${index}"`:''}>${editable?`<div class="block-tools">${small('↑','block-up:'+b.id)}${small('↓','block-down:'+b.id)}${small('편집','block-edit:'+b.id)}${small('삭제','block-delete:'+b.id)}</div>`:''}${content}</div>`;
}
function home(){
  const p=portfolio,hasProfile=p.name||p.role||p.intro;
  return `${header()}<main class="portfolio ${p.width==='wide'?'wide':''}">${p.cover?`<div class="folio-cover"><h1>Portfolio<span>.</span></h1></div>`:''}<div class="folio-layout"><section class="profile ${hasProfile?'filled':''}"><div class="section-caption"><span>01</span><h2>Profile</h2></div><div class="profile-content">${safeURL(p.image)?`<img class="avatar" src="${esc(safeURL(p.image))}" alt="">`:''}${p.name?`<h1>${esc(p.name)}</h1>`:''}${p.role?`<p class="role">${esc(p.role)}</p>`:''}${p.intro?`<p class="intro">${esc(p.intro)}</p>`:''}${p.email?`<a class="contact" href="mailto:${esc(encodeURIComponent(p.email))}">${esc(p.email)} ↗</a>`:''}</div></section><div class="folio-sections">${(p.sections||[]).map((section,i)=>`<section class="folio-section ${section.blocks?.length?'has-content':''}"><div class="section-caption"><span>${String(i+2).padStart(2,'0')}</span><h2>${esc(section.title)}</h2></div><div class="folio-section-content">${(section.blocks||[]).map(b=>renderBlock(b)).join('')}</div></section>`).join('')}</div></div><footer class="folio-footer"><span>kdh044</span><a href="#/planner">${icon('lock')} 플래너 ${icon('arrow')}</a></footer></main>`;
}
function login(){return `${header()}<main class="login-layout"><section class="login-panel"><div class="lock-badge">${icon('lock')}</div><h1>플래너</h1><form id="login-form"><label class="field"><span>비밀번호</span><input type="password" name="password" autocomplete="current-password" required ${!configured(config)||loading?'disabled':''}></label><button class="button primary full" type="submit" ${!configured(config)||loading?'disabled':''}>${loading?'불러오는 중…':'플래너 열기'}${icon('arrow')}</button><p id="login-error" class="form-error" role="alert"></p></form>${!configured(config)?`<p class="setup-note">아직 계정이 연결되지 않았습니다.</p>`:''}<div class="login-footer"><a class="back-link" href="#/">포트폴리오로</a>${btn('연결 설정','connection','quiet setup-link','settings')}</div></section></main>`;}
function sidebar(){const nav=[['today','sun','오늘'],['weekly','calendar','주간'],['plans','file','계획'],['projects','folder','프로젝트'],['calendar','calendar','캘린더'],['pages','file','페이지']];return `<aside class="sidebar"><a class="workspace-brand" href="#/"><span class="brand-mark">k.</span><div>플래너</div></a><label class="search-field">${icon('search')}<input id="workspace-search" aria-label="검색" value="${esc(query)}"></label><nav>${nav.map(([v,i,l])=>`<button data-action="view:${v}" class="side-nav ${view===v?'active':''}">${icon(i)}${l}${v==='pages'?`<span>${workspace.pages.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-pages">${workspace.pages.slice(0,6).map(p=>`<button data-action="page:${p.id}" class="page-nav ${view==='pages'&&selectedPage===p.id?'active':''}"><span class="page-dot"></span>${esc(p.title||'제목 없음')}</button>`).join('')}${btn('새 페이지','new-page','quiet','plus')}</div><div class="sidebar-bottom"><button class="side-nav ${view==='portfolio'?'active':''}" data-action="portfolio">${icon('grid')}포트폴리오 편집</button><button class="side-nav ${view==='settings'?'active':''}" data-action="view:settings">${icon('settings')}설정</button><button class="side-nav" data-action="logout">${icon('logout')}로그아웃</button><div class="private-note">${icon('lock')}비공개 워크스페이스</div></div></aside>`;}
function taskRow(t){const p=workspace.projects.find(x=>x.id===t.projectId);return `<div class="task-row"><button data-action="task-toggle:${t.id}" class="task-check ${t.status==='done'?'checked':''}" aria-label="완료 상태 변경">${t.status==='done'?icon('check'):''}</button><button class="task-title ${t.status==='done'?'done':''}" data-action="task-edit:${t.id}">${esc(t.title)}</button><div class="task-meta">${p?`<span>${esc(p.title)}</span>`:''}${t.category?`<span class="tag">${esc(t.category)}</span>`:''}${t.date?`<span class="task-date ${t.date<dateKey()&&t.status!=='done'?'overdue':''}">${esc(t.date.slice(5))}</span>`:''}</div>${small('편집','task-edit:'+t.id)}</div>`;}
function today(){const tasks=workspace.tasks.filter(t=>(!t.date||t.date<=dateKey())&&matches(t)),open=tasks.filter(t=>t.status!=='done'),done=tasks.filter(t=>t.status==='done'),all=tasks.length,percent=all?Math.round(done.length/all*100):0;return `<div class="page-heading"><div><h1>오늘</h1><p>${dateLabel(new Date())}</p></div>${btn('할 일 추가','new-task','primary','plus')}</div>${planningTabs()}<div class="today-grid"><section class="panel focus-card"><div class="panel-label">${icon('sun')}진행 현황<span>${percent}%</span></div><div class="focus-number">${open.length}<span>남은 할 일</span></div><div class="progress-track"><i style="width:${percent}%"></i></div><div class="focus-foot"><span>완료 ${done.length}</span><span>전체 ${all}</span></div></section><section class="panel note-card"><div class="panel-label">${icon('file')}하루 계획</div><textarea id="daily-plan" aria-label="하루 계획">${esc(workspace.dailyPlans[dateKey()]||'')}</textarea></section></div><section class="panel task-panel"><div class="panel-heading"><h2>할 일 <span>${open.length}</span></h2><span class="muted small-text">미정 · 오늘 · 지난 일정</span></div>${open.length?open.map(taskRow).join(''):`<div class="empty-state">${icon('check')}<p>할 일이 없습니다.</p>${btn('추가','new-task','quiet','plus')}</div>`}${done.length?`<details class="completed"><summary>완료한 일 ${done.length}</summary>${done.map(taskRow).join('')}</details>`:''}</section><details class="daily-memo"><summary>오늘의 메모</summary><textarea id="daily-note" aria-label="오늘의 메모">${esc(workspace.notes[dateKey()]||'')}</textarea></details><div class="section-head"><h2>진행 중인 프로젝트</h2>${btn('전체 보기','view:projects','quiet','arrow')}</div><div class="project-grid">${workspace.projects.filter(x=>x.status!=='done'&&matches(x)).slice(0,3).map(projectCard).join('')||`<button class="empty-project" data-action="new-project">${icon('plus')}프로젝트 추가</button>`}</div>`;}
function projectCard(p){const tasks=workspace.tasks.filter(t=>t.projectId===p.id),done=tasks.filter(t=>t.status==='done').length,pct=tasks.length?Math.round(done/tasks.length*100):0;return `<article class="project-card"><div class="project-top"><span class="project-icon">${icon('folder')}</span><span class="tag">${esc(p.category||'')}</span>${small('편집','project-edit:'+p.id)}</div><button class="project-title" data-action="project-open:${p.id}">${esc(p.title)}</button>${p.description?`<p>${esc(p.description)}</p>`:''}<div class="project-progress"><span>${done} / ${tasks.length}</span><span>${pct}%</span></div><div class="progress-track"><i style="width:${pct}%"></i></div><div class="project-bottom"><span>${esc(statusLabels[p.status]||'할 일')}</span><span>${esc(p.date||'')}</span></div></article>`;}

function planningTabs(){return `<nav class="planning-tabs" aria-label="계획 보기">${[['today','오늘'],['weekly','주간'],['plans','계획']].map(([v,l])=>`<button data-action="view:${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${l}</button>`).join('')}</nav>`;}
function deadlineStrip(){const deadlines=[...workspace.deadlines].sort((a,b)=>{const x=daysUntil(a.date),y=daysUntil(b.date);return (x<0)-(y<0)||a.date.localeCompare(b.date);});return `<section class="deadline-strip" aria-label="중요한 D-day"><div class="deadline-label">D-day${btn('추가','new-deadline','mini','plus')}</div><div class="deadline-items">${deadlines.slice(0,4).map(d=>`<button class="deadline-item ${daysUntil(d.date)===0?'due':''}" data-action="deadline-edit:${esc(d.id)}"><strong>${deadlineLabel(d.date)}</strong><span>${esc(d.title)}</span><time datetime="${d.date}">${d.date.slice(5).replace('-','.')}</time></button>`).join('')}</div>${deadlines.length>4?btn('전체 '+deadlines.length,'view:plans','quiet'):''}</section>`;}
function weekly(){const days=plannerWeek(new Date(weeklyAnchor+'T12:00:00')),first=dateKey(days[0]),last=dateKey(days[6]),tasks=workspace.tasks.filter(t=>matches(t)),pending=tasks.filter(t=>!t.date);return `<div class="page-heading"><div><h1>주간</h1><p>${dateLabel(days[0])} – ${dateLabel(days[6])}</p></div><div class="button-group">${btn('이전 주','week-prev','icon-only calendar-prev','chevron')}${btn('이번 주','week-today','quiet')}${btn('다음 주','week-next','icon-only','chevron')}${btn('할 일 추가','new-task','primary','plus')}</div></div>${planningTabs()}<section class="weekly-plan-card"><label for="weekly-plan">일주일 계획</label><textarea id="weekly-plan" aria-label="일주일 계획" data-week-key="${first}">${esc(workspace.weeklyPlans[first]||'')}</textarea></section><div class="weekly-todos">${days.map(d=>{const key=dateKey(d),items=tasks.filter(t=>t.date===key);return `<section class="weekly-todo-day ${key===dateKey()?'is-current':''}"><header><div><span>${d.toLocaleDateString('ko-KR',{weekday:'short'})}</span><h2>${d.getDate()}</h2></div><span>${items.filter(t=>t.status==='done').length}/${items.length}</span></header><div class="weekly-task-list">${items.map(t=>`<div class="weekly-task ${t.status==='done'?'done':''}"><button class="check-button ${t.status==='done'?'checked':''}" aria-label="${esc(t.title)} 완료 상태 변경" data-action="task-toggle:${t.id}">${t.status==='done'?icon('check'):''}</button><button class="weekly-task-title" data-action="task-edit:${t.id}">${esc(t.title)}</button></div>`).join('')}</div><button class="weekly-add" data-action="new-task-day:${key}">${icon('plus')}할 일</button></section>`;}).join('')}</div>${pending.length?`<section class="panel task-panel weekly-undated"><div class="panel-heading"><h2>날짜 미정 <span>${pending.length}</span></h2></div>${pending.map(taskRow).join('')}</section>`:''}`;}
function plans(){const d=new Date(planDate+'T12:00:00'),key=weekKey(d);return `<div class="page-heading"><div><h1>계획</h1></div><label class="plan-date field"><span>날짜</span><input id="plan-date" aria-label="계획 날짜" type="date" value="${planDate}" required></label></div>${planningTabs()}<div class="plan-editors"><section class="plan-editor"><label for="plan-daily">하루 계획</label><p>${dateLabel(d)}</p><textarea id="plan-daily" aria-label="하루 계획" data-plan-key="${planDate}">${esc(workspace.dailyPlans[planDate]||'')}</textarea></section><section class="plan-editor"><label for="plan-weekly">일주일 계획</label><p>${key.replaceAll('-','.')} – ${dateKey(plannerWeek(d)[6]).replaceAll('-','.')}</p><textarea id="plan-weekly" aria-label="일주일 계획" data-plan-key="${key}">${esc(workspace.weeklyPlans[key]||'')}</textarea></section></div><div class="section-head"><h2>D-day</h2>${btn('추가','new-deadline','quiet','plus')}</div><div class="deadline-list">${workspace.deadlines.map(x=>`<button class="deadline-row" data-action="deadline-edit:${esc(x.id)}"><strong>${deadlineLabel(x.date)}</strong><span>${esc(x.title)}</span><time datetime="${x.date}">${x.date}</time>${icon('chevron')}</button>`).join('')}</div>`;}
function deadlineDialog(id=''){const d=workspace.deadlines.find(x=>x.id===id)||{title:'',date:''};dialog(id?'D-day 편집':'D-day 추가',`${field('중요한 일정','title',d.title,'text',true)}${field('날짜','date',d.date,'date',true)}`,data=>{if(!data.title.trim()||!validDateKey(data.date))throw Error('일정과 날짜를 입력해주세요.');if(id)Object.assign(d,{title:data.title.trim(),date:data.date});else workspace.deadlines.push({id:uid(),title:data.title.trim(),date:data.date});changed();},id?btn('삭제','deadline-delete:'+id,'danger'):'');}

function projects(){const project=workspace.projects.find(x=>x.id===selectedProject),tasks=workspace.tasks.filter(t=>(!project||t.projectId===project.id)&&matches(t));return `<div class="page-heading"><div><h1>${project?esc(project.title):'프로젝트'}</h1>${project?.description?`<p>${esc(project.description)}</p>`:''}</div><div class="button-group">${project?btn('전체 프로젝트','project-back','quiet'):btn('프로젝트 추가','new-project','quiet','plus')}${btn('할 일 추가','new-task','primary','plus')}</div></div>${!project?`<div class="project-grid">${workspace.projects.filter(matches).map(projectCard).join('')||'<div class="empty-state compact"><p>프로젝트가 없습니다.</p></div>'}</div>`:''}<div class="section-head"><h2>작업 보드</h2><span class="muted small-text">드래그 또는 편집으로 상태 변경</span></div><div class="board">${Object.entries(statusLabels).map(([status,label])=>`<section class="board-column" data-drop-status="${status}"><div class="column-heading"><span class="status-dot ${status}"></span><h3>${label}</h3><span>${tasks.filter(t=>t.status===status).length}</span>${small('+','new-task:'+status)}</div><div class="board-cards">${tasks.filter(t=>t.status===status).map(t=>`<button class="board-card" draggable="true" data-task-drag="${t.id}" data-action="task-edit:${t.id}"><span>${esc(t.title)}</span><div>${t.category?`<span class="tag">${esc(t.category)}</span>`:''}${t.date?`<span>${esc(t.date.slice(5))}</span>`:''}</div></button>`).join('')}<button class="board-add" data-action="new-task:${status}">${icon('plus')}추가</button></div></section>`).join('')}</div>`;}
const eventClock=e=>e.start?.dateTime?new Date(e.start.dateTime).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',hour12:false}):(e.time||'');
const eventAction=e=>`${e.source==='google'?'google-event':'event-edit'}:${e.source==='google'?(e.googleKey||e.id):e.id}`;
const calendarColor=value=>/^#[0-9a-f]{6}$/i.test(value||'')?value:'#6580a5';
const eventColorStyle=e=>e.source==='google'?`style="--calendar-color:${calendarColor(e.calendarColor)}"`:'';
function selectedGoogleCalendars(){return Array.isArray(workspace.googleCalendarIds)?googleCalendars.filter(c=>workspace.googleCalendarIds.includes(c.id)):googleCalendars.filter(c=>c.primary||c.selected);}
function googleCalendarList(){
  if(!googleConnected())return '';
  const ids=new Set(selectedGoogleCalendars().map(c=>c.id));
  return `<section class="google-calendar-list" aria-label="표시할 Google 캘린더"><div><h3>표시할 캘린더</h3><div class="button-group">${btn('다시 연결','google-connect','mini')}${btn('연결 해제','google-disconnect','mini')}</div></div>${googleCalendars.map(c=>`<label class="google-calendar-choice"><input type="checkbox" data-google-calendar="${esc(c.id)}" ${ids.has(c.id)?'checked':''} ${googleLoading?'disabled':''}><i style="background:${calendarColor(c.backgroundColor)}"></i><span>${esc(c.summaryOverride||c.summary||'제목 없음')}</span></label>`).join('')}${!googleCalendars.length?'<p class="small-text muted">'+(googleLoading?'목록 불러오는 중':'캘린더 목록을 불러오지 못했습니다.')+'</p>':''}</section>`;
}
function calendar(){
  const days=calendarMode==='week'?weekCells(new Date(selectedDay+'T12:00:00')):monthCells(month);
  const events=[...workspace.events,...googleEvents.map(e=>({...e,source:'google',title:e.summary||'제목 없음'}))].sort((a,b)=>eventClock(a).localeCompare(eventClock(b)));
  const dayEvents=events.filter(e=>eventOnDay(e,selectedDay)),dayTasks=workspace.tasks.filter(t=>t.date===selectedDay);
  const visibleEvents=events.filter(e=>days.some(d=>eventOnDay(e,dateKey(d)))).length;
  const dateTitle=calendarMode==='week'?`${days[0].getMonth()+1}.${days[0].getDate()} — ${days[6].getMonth()+1}.${days[6].getDate()}`:`${month.getFullYear()}년 ${month.getMonth()+1}월`;
  const connected=googleConnected();
  return `<div class="page-heading calendar-heading"><div><span class="eyebrow">캘린더</span><h1>${dateTitle}</h1></div><div class="button-group">${btn(googleLoading?'불러오는 중…':connected?'새로고침':'Google 연결',connected?'google-refresh':'google-connect','quiet google-button','calendar')}${btn('일정 추가','new-event','primary','plus')}</div></div><div class="calendar-layout"><section class="panel calendar-panel"><div class="calendar-toolbar"><div class="calendar-period"><div class="button-group">${btn('이전','month-prev','icon-only calendar-prev','chevron')}${btn('다음','month-next','icon-only calendar-next','chevron')}</div><h2 class="sr-only">${dateTitle}</h2>${btn('오늘','month-today','quiet')}</div><div class="calendar-switch" role="group" aria-label="캘린더 보기"><button data-action="calendar-mode:month" aria-pressed="${calendarMode==='month'}">월</button><button data-action="calendar-mode:week" aria-pressed="${calendarMode==='week'}">주</button></div></div>${calendarMode==='month'?`<div class="calendar-weekdays">${['일','월','화','수','목','금','토'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${days.map(d=>{const key=dateKey(d),es=events.filter(e=>eventOnDay(e,key)),ts=workspace.tasks.filter(t=>t.date===key);return `<button data-action="day:${key}" aria-label="${dateLabel(d)}, 일정 ${es.length}개, 할 일 ${ts.length}개" aria-pressed="${key===selectedDay}" class="calendar-cell ${d.getMonth()!==month.getMonth()?'outside':''} ${key===selectedDay?'selected':''}"><span class="day-number ${key===dateKey()?'is-today':''}">${d.getDate()}</span><div>${es.slice(0,2).map(e=>`<span class="event-chip ${e.source==='google'?'google':''}" title="${esc(e.title)}"><i ${eventColorStyle(e)}></i>${esc(e.title)}</span>`).join('')}${ts.length?`<span class="task-chip">${icon('check')} ${ts.length}</span>`:''}${es.length>2?`<span class="more-events">+${es.length-2}개 더</span>`:''}</div></button>`;}).join('')}</div>`:`<div class="week-grid">${days.map(d=>{const key=dateKey(d),es=events.filter(e=>eventOnDay(e,key)),ts=workspace.tasks.filter(t=>t.date===key);return `<section class="week-column ${key===selectedDay?'selected':''}"><button class="week-day" data-action="day:${key}" aria-pressed="${key===selectedDay}"><span>${d.toLocaleDateString('ko-KR',{weekday:'short'})}</span><strong class="${key===dateKey()?'is-today':''}">${d.getDate()}</strong></button><div class="week-entries">${es.map(e=>`<button class="week-event ${e.source==='google'?'google':''}" ${eventColorStyle(e)} data-action="${eventAction(e)}"><small>${esc(eventClock(e)||'종일')}</small><span>${esc(e.title)}</span></button>`).join('')}${ts.map(t=>`<button class="week-task ${t.status==='done'?'done':''}" data-action="task-edit:${t.id}">${icon('check')}<span>${esc(t.title)}</span></button>`).join('')}${!es.length&&!ts.length?'<span class="week-empty" aria-hidden="true">—</span>':''}</div><button class="week-add" aria-label="${dateLabel(d)} 일정 추가" data-action="new-event-day:${key}">${icon('plus')}</button></section>`;}).join('')}</div>`}<div class="calendar-footer"><div class="calendar-legend"><span><i></i>내 일정</span><span><i class="google"></i>Google</span><span>${icon('check')}할 일</span></div><span>일정 ${visibleEvents}개</span></div></section><aside class="panel day-panel"><h2>${dateLabel(new Date(selectedDay+'T12:00:00'))}</h2><div class="day-events">${dayEvents.map(e=>`<button class="day-event ${e.source==='google'?'google':''}" ${eventColorStyle(e)} data-action="${eventAction(e)}"><small>${esc(eventClock(e)||'종일')}</small><span>${esc(e.title)}</span>${e.source==='google'?`<em>${esc(e.calendarName||'Google Calendar')}</em>`:''}</button>`).join('')||'<div class="day-empty">'+icon('calendar')+'<span>일정 없음</span></div>'}</div><div class="day-task-heading"><h3>할 일</h3><span>${dayTasks.length}</span>${btn('추가','new-task','mini','plus')}</div>${dayTasks.map(t=>`<button class="day-task ${t.status==='done'?'done':''}" data-action="task-edit:${t.id}">${icon('check')}<span>${esc(t.title)}</span></button>`).join('')||'<p class="muted day-task-empty">할 일 없음</p>'}<div class="google-status ${connected?'connected':''}"><span class="connection-dot"></span><div><strong>Google Calendar</strong><span>${googleLoading?'일정 불러오는 중':connected?'연결됨 · '+selectedGoogleCalendars().length+'개 캘린더':'연결 전'}</span></div>${btn('설정','google-setup','icon-only','settings')}</div>${googleCalendarList()}${googleError?`<p class="calendar-error" role="alert">${esc(googleError)}</p>`:''}</aside></div>`;
}
function pages(){const p=workspace.pages.find(x=>x.id===selectedPage);return `<div class="page-heading"><div><h1>페이지</h1></div>${btn('새 페이지','new-page','primary','plus')}</div><div class="pages-layout"><section class="panel page-list">${workspace.pages.filter(matches).map(x=>`<button class="page-list-item ${x.id===selectedPage?'active':''}" data-action="page:${x.id}">${icon('file')}<span>${esc(x.title||'제목 없음')}</span>${icon('chevron')}</button>`).join('')||'<p class="muted">페이지가 없습니다.</p>'}</section><section class="panel document">${p?`<div class="document-header"><input id="page-title" aria-label="페이지 제목" value="${esc(p.title)}">${small('삭제','page-delete:'+p.id)}</div><div class="document-blocks">${p.blocks.map((b,i)=>renderBlock(b,true,i)).join('')}</div><div class="add-block-bar">${btn('블록 추가','new-block','quiet','plus')}<span class="muted small-text">텍스트 · 제목 · 체크리스트 · 링크 · 이미지</span></div>`:`<div class="empty-state">${icon('file')}<p>페이지를 선택하거나 새로 만드세요.</p></div>`}</section></div>`;}
function portfolioEditor(){const p=workspace.portfolio;return `<div class="page-heading"><div><h1>포트폴리오 편집</h1><p>게시한 내용만 공개 화면에 나타납니다.</p></div><div class="button-group">${btn('미리보기','portfolio-preview','quiet')}${btn('공개하기','publish','primary','arrow')}</div></div><section class="panel portfolio-form"><h2>프로필</h2><div class="form-grid">${field('이름','name',p.name)}${field('직무 / 소속','role',p.role)}${field('이메일','email',p.email,'email')}${field('프로필 이미지 URL','image',p.image,'url')}</div>${area('소개','intro',p.intro)}<h2>레이아웃</h2><div class="form-grid">${field('강조 색상','accent',p.accent,'color')}${select('페이지 너비','width',[['normal','기본'],['wide','넓게']],p.width)}</div><label class="check-label"><input type="checkbox" name="cover" ${p.cover?'checked':''}>그래픽 커버 표시</label></section><div class="section-head"><h2>섹션</h2>${btn('섹션 추가','new-section','quiet','plus')}</div>${p.sections.map(s=>`<section class="panel editable-section"><div class="section-edit-heading"><input data-section-title="${s.id}" aria-label="섹션 이름" value="${esc(s.title)}"><div>${small('↑','section-up:'+s.id)}${small('↓','section-down:'+s.id)}${small('삭제','section-delete:'+s.id)}</div></div>${s.blocks.map(b=>`<div class="portfolio-block"><div>${renderBlock(b)}</div>${small('↑','portfolio-block-up:'+s.id+':'+b.id)}${small('↓','portfolio-block-down:'+s.id+':'+b.id)}${small('편집','portfolio-block-edit:'+s.id+':'+b.id)}${small('삭제','portfolio-block-delete:'+s.id+':'+b.id)}</div>`).join('')}${btn('블록 추가','portfolio-block-new:'+s.id,'quiet','plus')}</section>`).join('')}`;}
function settings(){return `<div class="page-heading"><div><h1>설정</h1></div></div><section class="panel settings-section"><div><h2>계정 연결</h2><p class="muted">비밀번호 로그인 · 비공개 저장</p></div>${btn('연결 설정','connection','quiet','settings')}</section><section class="panel settings-section"><div><h2>Google 캘린더</h2><p class="muted">${googleConnected()?'연결됨':'연결되지 않음'}</p></div>${btn(googleConnected()?'연결 해제':'연결하기',googleConnected()?'google-disconnect':'google-connect','quiet','calendar')}</section><section class="panel settings-section"><div><h2>분류</h2><p class="muted">${workspace.categories.map(esc).join(' · ')}</p></div>${btn('편집','categories','quiet')}</section><section class="panel settings-section"><div><h2>백업</h2><p class="muted">현재 워크스페이스를 JSON 파일로 보관합니다.</p></div><div class="button-group">${btn('내보내기','export','quiet','download')}${btn('가져오기','import','quiet')}</div></section>${saveError?`<section class="panel save-warning"><h2>저장하지 못한 변경이 있습니다.</h2><p>${esc(saveError)}</p>${btn('재시도','save','primary')}${btn('백업 내보내기','export','quiet')}</section>`:''}`;}
function planner(){const contents={today,weekly,plans,projects,calendar,pages,settings,portfolio:portfolioEditor};return `<div class="workspace-shell">${sidebar()}<div class="workspace-main"><header class="workspace-topbar"><div>${icon(view==='portfolio'?'grid':view==='settings'?'settings':view==='projects'?'folder':view==='calendar'?'calendar':view==='pages'?'file':'sun')}<span>My workspace</span><span class="breadcrumb">/</span><span>${{today:'오늘',weekly:'주간',plans:'계획',projects:'프로젝트',calendar:'캘린더',pages:'페이지',settings:'설정',portfolio:'포트폴리오'}[view]}</span></div><button id="save-status" data-action="save" class="save-status"></button></header><main class="workspace-content">${['today','weekly','plans'].includes(view)?deadlineStrip():''}${contents[view]()}</main></div></div>`;}
function render(){
  const isPrivate=location.hash.startsWith('#/planner');
  app.innerHTML=isPrivate?(ready?planner():login()):home();
  const accent=portfolio.accent||'#496954';document.documentElement.style.setProperty('--accent',/^#[0-9a-f]{6}$/i.test(accent)?accent:'#496954');setSaveStatus();
}
async function enter(){loading=true;render();try{workspace=normalizeWorkspace(await backend.load());ready=true;saveError='';dirty=false;}catch(err){backend.clear();ready=false;toast('플래너를 불러오지 못했습니다. '+err.message);}finally{loading=false;render();}}
function connectionDialog(){const c=config;dialog('연결 설정',`<p class="muted dialog-intro">계정 설정은 처음 한 번만 필요합니다.</p>${field('Supabase 프로젝트 URL','url',c.url,'url',true)}${field('Publishable / anon 공개 키','key',c.key,'text',true)}<div class="form-grid">${field('계정 이메일','email',c.email,'email',true)}${field('사용자 UID','owner',c.owner,'text',true)}</div>${field('Google OAuth Client ID','googleClientId',c.googleClientId)}<p class="small-text muted">비밀번호는 이 설정에 저장되지 않습니다. 공개 사이트에도 적용하려면 public/config.json에 이 연결 값을 넣어주세요.</p><a href="https://github.com/kdh044/kdh044.github.io/blob/main/SETUP.md" target="_blank" rel="noopener">연결 안내 보기 ↗</a>`,async data=>{if(ready)await flushSave();const next={...data,googleBaseClientId:sharedConfig.googleClientId||''};writeConfig(next);await backend.logout();config={...next,url:new URL(data.url).origin};backend=new Backend(config);ready=false;workspace=emptyWorkspace();clearGoogle();googleEvents=[];googleCalendars=[];googleRequestVersion++;portfolio=await backend.publicPortfolio().catch(()=>null)||emptyPortfolio();render();toast('연결 설정을 저장했습니다.');},btn('Google 기본 설정 사용','google-default','quiet'));}
function taskDialog(id='',status='todo',taskDate=''){const t=workspace.tasks.find(x=>x.id===id)||{title:'',date:taskDate||(view==='calendar'?selectedDay:view==='weekly'?(plannerWeek(new Date(weeklyAnchor+'T12:00:00')).some(d=>dateKey(d)===dateKey())?dateKey():weekKey(new Date(weeklyAnchor+'T12:00:00'))):dateKey()),category:'',status,projectId:selectedProject,description:''};dialog(id?'할 일 편집':'할 일 추가',`${field('할 일','title',t.title,'text',true)}<div class="form-grid">${field('날짜','date',t.date,'date')}${select('상태','status',Object.entries(statusLabels),t.status)}${select('분류','category',[['','선택 안 함'],...workspace.categories.map(c=>[c,c])],t.category)}${select('프로젝트','projectId',[['','선택 안 함'],...workspace.projects.map(p=>[p.id,p.title])],t.projectId)}</div>${area('메모','description',t.description)}`,data=>{if(id)Object.assign(t,data);else workspace.tasks.push({id:uid(),...data});changed();},id?btn('삭제','task-delete:'+id,'danger'): '');}
function projectDialog(id=''){const p=workspace.projects.find(x=>x.id===id)||{title:'',category:'',status:'todo',date:'',description:''};dialog(id?'프로젝트 편집':'프로젝트 추가',`${field('프로젝트 이름','title',p.title,'text',true)}${area('설명','description',p.description)}<div class="form-grid">${select('분류','category',[['','선택 안 함'],...workspace.categories.map(c=>[c,c])],p.category)}${select('상태','status',Object.entries(statusLabels),p.status)}${field('목표 날짜','date',p.date,'date')}</div>`,data=>{if(id)Object.assign(p,data);else workspace.projects.push({id:uid(),...data});changed();},id?btn('삭제','project-delete:'+id,'danger'):'');}
function eventDialog(id=''){const e=workspace.events.find(x=>x.id===id)||{title:'',date:selectedDay,time:'',description:''};dialog(id?'일정 편집':'일정 추가',`${field('일정 제목','title',e.title,'text',true)}<div class="form-grid">${field('날짜','date',e.date,'date',true)}${field('시간','time',e.time,'time')}</div>${area('메모','description',e.description)}${!id?`<label class="check-label"><input type="checkbox" name="google" ${googleConnected()?'checked':''} ${!googleConnected()?'disabled':''}>Google 캘린더에 추가</label>`:''}`,async data=>{if(data.google){const epoch=backend.epoch;await addGoogleEvent(data);if(backend.epoch!==epoch||!ready)return;await refreshGoogle();toast('Google 기본 캘린더에 추가했습니다.');}else{if(id)Object.assign(e,data);else workspace.events.push({id:uid(),...data});changed();}},id?btn('삭제','event-delete:'+id,'danger'):'');}
function blockDialog(id='',sectionId=''){const blocks=sectionId?workspace.portfolio.sections.find(s=>s.id===sectionId)?.blocks:workspace.pages.find(p=>p.id===selectedPage)?.blocks;if(!blocks)return;const b=blocks.find(x=>x.id===id)||{type:'text',text:'',url:'',checked:false};dialog(id?'블록 편집':'블록 추가',`${select('블록 종류','type',[['text','텍스트'],['heading','제목'],['checkbox','체크리스트'],['divider','구분선'],['link','링크'],['image','이미지']],b.type)}${area('내용','text',b.text)}${field('링크 / 이미지 URL','url',b.url,'url')}`,data=>{if(['link','image'].includes(data.type)&&!safeURL(data.url))throw Error('유효한 URL을 입력해주세요.');if(id)Object.assign(b,data);else blocks.push({id:uid(),checked:false,...data});changed();});}
function googleSetupDialog(){
  dialog('Google Calendar 연결',`<p class="dialog-intro">Google 계정을 승인하면 일정이 캘린더에 표시됩니다.</p>${field('OAuth Client ID','googleClientId',config.googleClientId||'')}<details class="google-setup-help"><summary>처음 연결하는 경우</summary><ol><li>Google Cloud에서 Calendar API를 사용 설정합니다.</li><li>Google Auth Platform에 웹 애플리케이션 OAuth 클라이언트를 만듭니다.</li><li>승인된 JavaScript 원본에 아래 주소를 등록합니다.</li></ol><code>https://kdh044.github.io</code><p>테스트 모드에서는 사용할 Google 계정을 테스트 사용자로 추가하세요. Client secret은 입력하지 않습니다.</p><a href="https://console.cloud.google.com/" target="_blank" rel="noopener">Google Cloud 열기 ↗</a></details><p class="small-text muted">Google에서 오류가 표시되면 이 ID가 오류에 사용된 client_id와 같은지 확인해주세요. 새 설정은 이 브라우저에 저장됩니다.</p>`,data=>{
    const id=data.googleClientId.trim();if(!/^\d+-[a-zA-Z0-9_-]+\.apps\.googleusercontent\.com$/.test(id))throw Error('웹 애플리케이션 OAuth Client ID를 확인해주세요.');
    setGoogleClient(id);toast('Google 연결 설정을 저장했습니다. Google 연결을 눌러 승인해주세요.');
  },btn('사이트 기본 설정 사용','google-default','quiet'));
}
function setGoogleClient(id){
  const next={...config,googleClientId:id,googleBaseClientId:sharedConfig.googleClientId||''};writeConfig(next);
  if(id!==config.googleClientId){clearGoogle();googleEvents=[];googleCalendars=[];googleRequestVersion++;googleLoading=false;googleError='';}
  config=next;backend.config=next;if(id)prepareGoogle().catch(()=>{});render();
}
async function refreshGoogle(refreshCalendars=false){
  const epoch=backend.epoch,request=++googleRequestVersion,requestedMonth=new Date(month),mode=calendarMode;
  const current=()=>ready&&epoch===backend.epoch&&request===googleRequestVersion;
  const days=mode==='week'?weekCells(new Date(selectedDay+'T12:00:00')):monthCells(requestedMonth);
  const end=new Date(days.at(-1));end.setDate(end.getDate()+1);
  googleLoading=true;googleError='';render();
  try{
    if(refreshCalendars||!googleCalendars.length){const calendars=await listGoogleCalendars();if(!current())return;googleCalendars=calendars;}
    const selected=selectedGoogleCalendars();
    const results=await Promise.allSettled(selected.map(c=>listGoogleEvents(requestedMonth,{start:days[0],end},c)));
    if(!current())return;
    googleEvents=results.flatMap(r=>r.status==='fulfilled'?r.value:[]);
    const failures=results.flatMap((r,i)=>r.status==='rejected'?[`${selected[i].summaryOverride||selected[i].summary||'Google Calendar'}: ${r.reason.message}`]:[]);
    googleError=failures.join(' / ');
  }catch(err){if(current()){googleEvents=[];googleError=err.message;toast('Google 일정을 불러오지 못했습니다. '+err.message);}}
  finally{if(current()){googleLoading=false;render();}}
}
function validImport(w){
  const validId=id=>typeof id==='string'&&/^[a-zA-Z0-9_-]{1,80}$/.test(id);
  const validBlocks=bs=>Array.isArray(bs)&&bs.every(b=>validId(b.id)&&['text','heading','checkbox','divider','image','link'].includes(b.type)&&typeof b.text==='string'&&(!b.url||typeof b.url==='string'));
  const plansValid=w&&['dailyPlans','weeklyPlans'].every(k=>w[k]===undefined||(w[k]&&typeof w[k]==='object'&&!Array.isArray(w[k])&&Object.entries(w[k]).every(([key,text])=>validDateKey(key)&&typeof text==='string')))&&(!w.deadlines||(Array.isArray(w.deadlines)&&w.deadlines.every(x=>x&&validId(x.id)&&typeof x.title==='string'&&validDateKey(x.date))));
  return plansValid&&w&&['tasks','projects','pages','events','categories'].every(k=>Array.isArray(w[k]))&&['tasks','projects','pages','events'].every(k=>w[k].every(x=>validId(x.id)&&typeof x.title==='string'))&&w.pages.every(p=>validBlocks(p.blocks))&&w.categories.every(c=>typeof c==='string')&&w.notes&&typeof w.notes==='object'&&Object.values(w.notes).every(x=>typeof x==='string')&&w.portfolio&&Array.isArray(w.portfolio.sections)&&w.portfolio.sections.every(s=>validId(s.id)&&typeof s.title==='string'&&validBlocks(s.blocks));
}
function downloadBackup(){const data=JSON.stringify({version:1,exportedAt:new Date().toISOString(),workspace},null,2),url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`workspace-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function action(a){
  const [name,id,extra]=a.split(':');
  if(name==='close'){closeDialog();return;}if(name==='connection'){connectionDialog();return;}if(name==='google-default'){setGoogleClient(sharedConfig.googleClientId||'');closeDialog();toast('Google 연결에 사이트 기본 설정을 적용했습니다.');return;}
  if(!ready)return;
  switch(name){
    case 'view':view=id;selectedProject='';render();if(view==='calendar'&&googleConnected())await refreshGoogle();break;
    case 'portfolio':view='portfolio';location.hash='#/planner';render();break;
    case 'portfolio-preview':previewing=true;portfolio=structuredClone(workspace.portfolio);location.hash='#/';render();toast('편집 중인 초안 미리보기입니다.');break;
    case 'publish':previewing=false;await flushSave();await backend.publish(workspace.portfolio);portfolio=structuredClone(workspace.portfolio);toast('포트폴리오를 공개했습니다.');break;
    case 'save':await flushSave();break;
    case 'logout':await flushSave();try{await backend.logout();}finally{clearTimeout(saveTimer);ready=false;workspace=emptyWorkspace();googleEvents=[];googleCalendars=[];googleRequestVersion++;clearGoogle();closeDialog();portfolio=await backend.publicPortfolio().catch(()=>null)||emptyPortfolio();render();}break;
    case 'new-task':taskDialog('',id||'todo');break;
    case 'new-task-day':taskDialog('','todo',id);break;
    case 'week-prev':case 'week-next':{const d=new Date(weeklyAnchor+'T12:00:00');d.setDate(d.getDate()+(name==='week-prev'?-7:7));weeklyAnchor=dateKey(d);render();break;}
    case 'week-today':weeklyAnchor=dateKey();render();break;
    case 'new-deadline':deadlineDialog();break;
    case 'deadline-edit':deadlineDialog(id);break;
    case 'deadline-delete':workspace.deadlines=workspace.deadlines.filter(x=>x.id!==id);closeDialog();changed();break;
    case 'task-edit':taskDialog(id);break;
    case 'task-toggle':{const t=workspace.tasks.find(x=>x.id===id);t.status=t.status==='done'?'todo':'done';changed();break;}
    case 'task-delete':workspace.tasks=workspace.tasks.filter(t=>t.id!==id);closeDialog();changed();break;
    case 'new-project':projectDialog();break;
    case 'project-edit':projectDialog(id);break;
    case 'project-open':selectedProject=id;view='projects';render();break;
    case 'project-back':selectedProject='';render();break;
    case 'project-delete':workspace.projects=workspace.projects.filter(p=>p.id!==id);workspace.tasks.forEach(t=>{if(t.projectId===id)t.projectId='';});if(selectedProject===id)selectedProject='';closeDialog();changed();break;
    case 'new-page':dialog('새 페이지',field('페이지 이름','title','','text',true),data=>{const p={id:uid(),title:data.title,blocks:[]};workspace.pages.push(p);selectedPage=p.id;view='pages';changed();});break;
    case 'page':selectedPage=id;view='pages';render();break;
    case 'page-delete':if(!confirm('이 페이지와 블록을 삭제할까요?'))return;workspace.pages=workspace.pages.filter(p=>p.id!==id);selectedPage=workspace.pages[0]?.id||null;changed();break;
    case 'new-block':blockDialog();break;
    case 'block-edit':blockDialog(id);break;
    case 'block-delete':case 'block-up':case 'block-down':{const p=workspace.pages.find(x=>x.id===selectedPage);if(name==='block-delete')p.blocks=p.blocks.filter(b=>b.id!==id);else moveItem(p.blocks,id,name==='block-up'?-1:1);changed();break;}
    case 'new-section':dialog('섹션 추가',field('섹션 이름','title','','text',true),data=>{workspace.portfolio.sections.push({id:uid(),title:data.title,blocks:[]});changed();});break;
    case 'section-up':case 'section-down':moveItem(workspace.portfolio.sections,id,name==='section-up'?-1:1);changed();break;
    case 'section-delete':if(!confirm('이 섹션과 블록을 삭제할까요?'))return;workspace.portfolio.sections=workspace.portfolio.sections.filter(s=>s.id!==id);changed();break;
    case 'portfolio-block-new':blockDialog('',id);break;
    case 'portfolio-block-edit':blockDialog(extra,id);break;
    case 'portfolio-block-up':case 'portfolio-block-down':case 'portfolio-block-delete':{const s=workspace.portfolio.sections.find(x=>x.id===id);if(name==='portfolio-block-delete')s.blocks=s.blocks.filter(b=>b.id!==extra);else moveItem(s.blocks,extra,name==='portfolio-block-up'?-1:1);changed();break;}
    case 'calendar-mode':calendarMode=id==='week'?'week':'month';render();if(googleConnected())await refreshGoogle();break;
    case 'month-prev':case 'month-next':{const direction=name==='month-prev'?-1:1;if(calendarMode==='week'){const next=new Date(selectedDay+'T12:00:00');next.setDate(next.getDate()+direction*7);selectedDay=dateKey(next);month=next;}else{month=new Date(month.getFullYear(),month.getMonth()+direction,1);selectedDay=dateKey(month);}googleEvents=[];render();if(googleConnected())await refreshGoogle();break;}
    case 'month-today':month=new Date();selectedDay=dateKey();googleEvents=[];render();if(googleConnected())await refreshGoogle();break;
    case 'day':selectedDay=id;render();break;
    case 'new-event-day':selectedDay=id;eventDialog();break;
    case 'new-event':eventDialog();break;
    case 'event-edit':eventDialog(id);break;
    case 'event-delete':workspace.events=workspace.events.filter(e=>e.id!==id);closeDialog();changed();break;
    case 'google-event':{const e=googleEvents.find(e=>(e.googleKey||e.id)===id);if(!e)return;dialog('Google 캘린더 일정',`<p class="small-text muted">${esc(e.calendarName||'Google Calendar')}</p><h3>${esc(e.summary||'제목 없음')}</h3><p>${esc(e.start?.dateTime||e.start?.date||'')}</p><p class="prewrap">${esc(e.description||'')}</p>${safeURL(e.htmlLink)?`<a href="${esc(safeURL(e.htmlLink))}" target="_blank" rel="noopener">Google 캘린더에서 편집 ↗</a>`:''}`,()=>{});modalRoot.querySelector('[type="submit"]').textContent='닫기';break;}
    case 'google-setup':googleSetupDialog();break;
    case 'google-connect':if(!config.googleClientId){googleSetupDialog();break;}await connectGoogle(config.googleClientId);if(ready){view='calendar';await refreshGoogle(true);}else clearGoogle();break;
    case 'google-refresh':await refreshGoogle(true);break;
    case 'google-disconnect':googleRequestVersion++;googleError='';googleLoading=false;clearGoogle();googleEvents=[];googleCalendars=[];render();break;
    case 'categories':dialog('분류 편집',area('한 줄에 하나씩 입력','categories',workspace.categories.join('\n')),data=>{workspace.categories=[...new Set(data.categories.split('\n').map(x=>x.trim()).filter(Boolean))];changed();});break;
    case 'export':downloadBackup();break;
    case 'import':{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(file.size>5*1024*1024)throw Error('5MB 이하 파일을 사용해주세요.');const v=JSON.parse(await file.text());if(v.version!==1||!validImport(v.workspace))throw Error('워크스페이스 백업 파일을 선택해주세요.');if(!confirm('현재 내용을 백업 파일로 교체할까요?'))return;workspace=normalizeWorkspace(v.workspace);selectedPage=null;selectedProject='';changed();toast('백업을 가져왔습니다.');}catch(e){toast(e.message);}};input.click();break;}
  }
}
app.addEventListener('submit',async e=>{if(e.target.id!=='login-form')return;e.preventDefault();const input=e.target.elements.password,b=e.submitter,password=input.value;input.value='';b.disabled=true;try{await backend.login(password);await enter();}catch(err){document.querySelector('#login-error').textContent=err.status===400?'비밀번호 또는 계정 설정을 확인해주세요.':err.message;b.disabled=false;}});
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target){action(target.dataset.action).catch(err=>toast(err.message));}});
app.addEventListener('input',e=>{if(!ready)return;const t=e.target;if(t.id==='workspace-search'){query=t.value;const start=t.selectionStart;render();const next=document.querySelector('#workspace-search');next.focus();next.setSelectionRange(start,start);return;}if(t.id==='daily-plan'){workspace.dailyPlans[dateKey()]=t.value;changed(false);}if(t.id==='weekly-plan'){workspace.weeklyPlans[t.dataset.weekKey]=t.value;changed(false);}if(t.id==='plan-daily'){workspace.dailyPlans[t.dataset.planKey]=t.value;changed(false);}if(t.id==='plan-weekly'){workspace.weeklyPlans[t.dataset.planKey]=t.value;changed(false);}if(t.id==='daily-note'){workspace.notes[dateKey()]=t.value;changed(false);}if(t.id==='page-title'){const p=workspace.pages.find(p=>p.id===selectedPage);p.title=t.value;changed(false);}if(t.dataset.sectionTitle){workspace.portfolio.sections.find(s=>s.id===t.dataset.sectionTitle).title=t.value;changed(false);}if(t.closest('.portfolio-form')&&t.name){workspace.portfolio[t.name]=t.type==='checkbox'?t.checked:t.value;changed(false);}});
app.addEventListener('change',e=>{if(ready&&e.target.id==='plan-date'){if(validDateKey(e.target.value)){planDate=e.target.value;render();}return;}const calendarId=e.target.dataset.googleCalendar;if(ready&&calendarId){const ids=new Set(selectedGoogleCalendars().map(c=>c.id));if(e.target.checked)ids.add(calendarId);else ids.delete(calendarId);workspace.googleCalendarIds=[...ids];googleEvents=googleEvents.filter(x=>ids.has(x.calendarId));changed();refreshGoogle().catch(err=>toast(err.message));return;}const id=e.target.dataset.checkBlock;if(ready&&id){const b=workspace.pages.find(p=>p.id===selectedPage)?.blocks.find(b=>b.id===id);if(b){b.checked=e.target.checked;changed(false);}}});
app.addEventListener('dragstart',e=>{const task=e.target.closest('[data-task-drag]'),block=e.target.closest('[data-block-drag]');if(task)dragged={kind:'task',id:task.dataset.taskDrag};else if(block)dragged={kind:'block',id:block.dataset.blockDrag};if(dragged){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragged.id);}});
app.addEventListener('dragover',e=>{if(dragged&&e.target.closest('[data-drop-status],[data-block-index]'))e.preventDefault();});
app.addEventListener('drop',e=>{e.preventDefault();if(!ready||!dragged)return;const col=e.target.closest('[data-drop-status]'),block=e.target.closest('[data-block-index]');if(dragged.kind==='task'&&col){workspace.tasks.find(t=>t.id===dragged.id).status=col.dataset.dropStatus;changed();}if(dragged.kind==='block'&&block){const blocks=workspace.pages.find(p=>p.id===selectedPage).blocks,at=blocks.findIndex(b=>b.id===dragged.id),to=Number(block.dataset.blockIndex);blocks.splice(to,0,blocks.splice(at,1)[0]);changed();}dragged=null;});
app.addEventListener('dragend',()=>dragged=null);
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#/planner'))previewing=false;if(!location.hash.startsWith('#/planner')&&!previewing)backend?.publicPortfolio().then(p=>{portfolio=p||emptyPortfolio();render();}).catch(()=>{});render();});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='s'&&ready){e.preventDefault();flushSave().catch(()=>{});}});
async function init(){
  let shared={};try{shared=await fetch('/config.json',{cache:'no-store'}).then(r=>r.json());}catch{}
  sharedConfig=shared;config=mergeConfig(sharedConfig,readConfig());backend=new Backend(config);if(config.googleClientId)prepareGoogle().catch(()=>{});render();
  if('serviceWorker' in navigator)navigator.serviceWorker.getRegistrations().then(rs=>{for(const r of rs)if(r.active?.scriptURL.endsWith('/sw.js'))r.update();}).catch(()=>{});
  if(await backend.restore())await enter();
  try{portfolio=await backend.publicPortfolio()||emptyPortfolio();}catch{portfolio=emptyPortfolio();}render();
}
init();
